# Development environment with docker
services.docker.enable = true;
services.docker.package = pkgs.docker;

environment.systemPackages = with pkgs; [
  git vim curl wget
  nodejs python3 rustc
];

# Development settings
services.docker.extraConfig = ''
  log_level = debug
  reload_on_change = true
'';

nix.gc = {
  automatic = true;
  dates = "weekly";
  options = "--delete-older-than 7d";
};
nix.optimise.automatic = true;

nix.gc = {
  automatic = true;
  dates = "weekly";
  options = "--delete-older-than 7d";
};
nix.optimise.automatic = true;

virtualisation.docker = {
  enable = true;
  enableOnBoot = true;
  autoPrune.enable = true;
};

services.postgresql = {
  enable = true;
  package = pkgs.postgresql_15;

  authentication = pkgs.lib.mkOverride 10 ''
    local all all trust

  '';
};

# Development environment with mysql
services.mysql.enable = true;
services.mysql.package = pkgs.mysql;

environment.systemPackages = with pkgs; [
  git vim curl wget
  nodejs python3 rustc
];

# Development settings
services.mysql.extraConfig = ''
  log_level = debug
  reload_on_change = true
'';

# Development environment with nginx
services.nginx.enable = true;
services.nginx.package = pkgs.nginx;

environment.systemPackages = with pkgs; [
  git vim curl wget
  nodejs python3 rustc
];

# Development settings
services.nginx.extraConfig = ''
  log_level = debug
  reload_on_change = true
'';

services.postgresql = {
  enable = true;
  package = pkgs.postgresql_15;
  enableTCPIP = true;
  authentication = pkgs.lib.mkOverride 10 ''
    local all all trust
    host all all 0.0.0.0/0 md5
  '';
};

# Development environment with audio
